import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"طیاروں کے درمیان مواصلاتی ٹیکنالوجی","description":"","frontmatter":{},"headers":[],"relativePath":"ur/0066-跨位面通讯技术.md","filePath":"ur/0066-跨位面通讯技术.md"}'),o={name:"ur/0066-跨位面通讯技术.md"};function l(h,t,i,n,s,u){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="طیاروں-کے-درمیان-مواصلاتی-ٹیکنالوجی" tabindex="-1">طیاروں کے درمیان مواصلاتی ٹیکنالوجی <a class="header-anchor" href="#طیاروں-کے-درمیان-مواصلاتی-ٹیکنالوجی" aria-label="Permalink to &quot;طیاروں کے درمیان مواصلاتی ٹیکنالوجی&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>66</td></tr><tr><td>ماڈیول</td><td>ٹیکنالوجی اور توانائی کا نظام</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>طیاروں کے درمیان مواصلات، خلا کی تہہ، اینکر نیٹ ورک، معلومات کی ترسیل، قانون کی انکوڈنگ</td></tr></tbody></table><h2 id="_1-طیاروں-کے-درمیان-مواصلاتی-ٹیکنالوجی-کے-چیلنجز" tabindex="-1">1. طیاروں کے درمیان مواصلاتی ٹیکنالوجی کے چیلنجز <a class="header-anchor" href="#_1-طیاروں-کے-درمیان-مواصلاتی-ٹیکنالوجی-کے-چیلنجز" aria-label="Permalink to &quot;1. طیاروں کے درمیان مواصلاتی ٹیکنالوجی کے چیلنجز&quot;">​</a></h2><p>روایتی واحد طیارے میں، مواصلاتی ٹیکنالوجی بنیادی ذریعہ کے طور پر برقی مقناطیسی لہریں استعمال کرتی ہے، اس کی ترسیل کی رفتار روشنی کی رفتار سے محدود ہے، اور ترسیل کی دوری سگنل کے کمی سے محدود ہے۔ جبکہ ہینگیوانزھو کے کثیر طیارہ ڈھانچے میں، طیاروں کے درمیان براہ راست جسمانی خلا کا کوئی رابطہ نہیں ہے، برقی مقناطیسی لہریں طیاروں کے درمیان رکاوٹ کو عبور نہیں کر سکتیں، اور روایتی مواصلاتی ٹیکنالوجی مکمل طور پر ناکام ہو جاتی ہے۔</p><p>طیاروں کے درمیان مواصلاتی ٹیکنالوجی بالکل وہی ہے جو اس مسئلے کو حل کرنے کے لیے تیار کی گئی قانون کی انجینئرنگ کی سطح کی ٹیکنالوجی ہے۔ یہ خلائی قانون کی شیڈولنگ کے نظام اور اینکر نیٹ ورک پر مبنی ہے، اور قانون کی انکوڈنگ اور خلا کی تہہ کے ذریعے مختلف طیاروں کے درمیان مستحکم معلوماتی ترسیل کا چینل قائم کرتا ہے۔ یہ ٹیکنالوجی سمبیوٹک تہذیب کے لیے &quot;تمام نسلوں کی مشترکہ ترقی&quot; کو حاصل کرنے کی بنیادی بنیادی ڈھانچہ ہے — طیاروں کے درمیان مواصلات کے بغیر، ان گنت طیاروں میں بکھری ہوئی زندگی متحد سمبیوٹک نیٹ ورک نہیں بنا سکتی۔</p><h2 id="_2-طیاروں-کے-درمیان-مواصلات-کا-بنیادی-اصول" tabindex="-1">2. طیاروں کے درمیان مواصلات کا بنیادی اصول <a class="header-anchor" href="#_2-طیاروں-کے-درمیان-مواصلات-کا-بنیادی-اصول" aria-label="Permalink to &quot;2. طیاروں کے درمیان مواصلات کا بنیادی اصول&quot;">​</a></h2><p>طیاروں کے درمیان مواصلات کے بنیادی اصول کو چار مراحل کے عمل کے طور پر خلاصہ کیا جا سکتا ہے: &quot;قانون کی انکوڈنگ — خلا کی سرنگ — اینکر ریلے — قانون کی ڈیکوڈنگ&quot;:</p><table tabindex="0"><thead><tr><th>مرحلہ</th><th>نام</th><th>ٹیکنالوجی کی وضاحت</th><th>کلیدی پیرامیٹرز</th></tr></thead><tbody><tr><td>پہلا مرحلہ</td><td>قانون کی انکوڈنگ</td><td>منتقل کی جانے والی معلومات کو مخصوص تعدد کے قانون کے اتار چڑھاؤ میں انکوڈ کرنا، برقی مقناطیسی لہریں نہیں</td><td>انکوڈنگ کی کارکردگی تقریباً 10^12 بٹ/قانون چکر</td></tr><tr><td>دوسرا مرحلہ</td><td>خلا کی سرنگ</td><td>خلائی قانون کی ٹیکنالوجی کا استعمال کرتے ہوئے طیاروں کے درمیان رکاوٹ پر عارضی خوردبین خلا کا چینل کھولنا، قانون کے اتار چڑھاؤ چینل کے ذریعے ہدف والے طیارے تک سرنگ کرتے ہیں</td><td>چینل کا قطر تقریباً 10^-15 میٹر، مدت بہت مختصر</td></tr><tr><td>تیسرا مرحلہ</td><td>اینکر ریلے</td><td>قانون کے اتار چڑھاؤ اینکر نیٹ ورک کے ذریعے ریلے بڑھاو اور روٹنگ سے گزرتے ہیں، طویل فاصلے کی ترسیل کے استحکام کو یقینی بناتے ہیں</td><td>ریلے میں تاخیر تقریباً 0.001 سیکنڈ/ہاپ</td></tr><tr><td>چوتھا مرحلہ</td><td>قانون کی ڈیکوڈنگ</td><td>وصول کرنے والا سرہ قانون کے اتار چڑھاؤ کو اصل معلومات میں بحال کرتا ہے، مکمل ہونے کی تصدیق کے بعد صارف کو دیتا ہے</td><td>ڈیکوڈنگ کی خرابی کی شرح 10^-12 سے کم</td></tr></tbody></table><p>روایتی مواصلات سے مختلف، طیاروں کے درمیان مواصلات کا معلوماتی ذریعہ قانون کے اتار چڑھاؤ ہے، برقی مقناطیسی لہریں نہیں۔ قانون کے اتار چڑھاؤ روشنی کی رفتار سے محدود نہیں ہیں، طیاروں کے درمیان تقریباً ریئل ٹائم ترسیل کو عملی جامہ پہنا سکتے ہیں، اور اس کی نظریاتی تاخیر بنیادی طور پر اینکر ریلے کے پروسیسنگ کے وقت سے آتی ہے۔</p><h2 id="_3-طیاروں-کے-درمیان-مواصلاتی-نیٹ-ورک-کی-آرکیٹیکچر" tabindex="-1">3. طیاروں کے درمیان مواصلاتی نیٹ ورک کی آرکیٹیکچر <a class="header-anchor" href="#_3-طیاروں-کے-درمیان-مواصلاتی-نیٹ-ورک-کی-آرکیٹیکچر" aria-label="Permalink to &quot;3. طیاروں کے درمیان مواصلاتی نیٹ ورک کی آرکیٹیکچر&quot;">​</a></h2><p>طیاروں کے درمیان مواصلاتی نیٹ ورک تین سطحوں والی آرکیٹیکچر اپناتا ہے: &quot;اینکر بیک بون — طیارہ ایکسیس — ٹرمینل ڈیوائس&quot;:</p><ol><li><strong>اینکر بیک بون نیٹ ورک</strong>: اہم طیاروں پر نافذ کردہ مرکزی اینکرز پر مشتمل، یہ طیاروں کے درمیان مواصلات کا مرکزی بیک بون ہے۔ مرکزی اینکرز ایک دوسرے سے اعلی بینڈوڈتھ والے قانون کے چینلز کے ذریعے منسلک ہوتے ہیں، واحد چینل کی بینڈوڈتھ 10^15 بٹ/سیکنڈ تک پہنچ سکتی ہے۔ بیک بون نیٹ ورک ملٹی پاتھ ریزنڈنسی ڈیزائن اپناتا ہے، واحد چینل کی خرابی مجموعی کنیکٹیویٹی کو متاثر نہیں کرتی</li><li><strong>طیارہ ایکسیس نیٹ ورک</strong>: ہر طیارے کے اندر، ثانوی اینکرز اور خلائی قانون بیس اسٹیشن اس طیارے کے ایکسیس نیٹ ورک کی تشکیل کرتے ہیں۔ ایکسیس نیٹ ورک ٹرمینل ڈیوائسز کے سگنلز کو اینکر بیک بون نیٹ ورک سے منسلک کرنے کا ذمہ دار ہے، ساتھ ہی بیک بون نیٹ ورک کی معلومات کو ٹرمینلز تک تقسیم کرتا ہے</li><li><strong>ٹرمینل ڈیوائس</strong>: سادگی کرنے والوں اور اداروں کے ذریعے استعمال ہونے والے طیاروں کے درمیان مواصلاتی ٹرمینلز، بشمول ذاتی کمیونیکیٹر، مقامی کمیونیکیشن اسٹیشن، ایمبیڈڈ کمیونیکیشن ماڈیول وغیرہ۔ ٹرمینل ڈیوائسز میں چھوٹا قانون انکوڈر-ڈیکوڈر لگا ہوا ہے، جو براہ راست ایکسیس نیٹ ورک کے ساتھ بات چیت کر سکتا ہے</li></ol><p>مواصلاتی نیٹ ورک کا روٹنگ الگورتھم اینکر نیٹ ورک کے سمبیوٹک تاثرات کے نظام پر مبنی ہے، ہر چینل کے بوجھ اور استحکام کو ریئل ٹائم میں محسوس کر سکتا ہے، اور متحرک طور پر بہترین ترسیل کا راستہ منتخب کر سکتا ہے۔</p><h2 id="_4-مواصلات-کی-سطح-اور-خدمات-کی-اقسام" tabindex="-1">4. مواصلات کی سطح اور خدمات کی اقسام <a class="header-anchor" href="#_4-مواصلات-کی-سطح-اور-خدمات-کی-اقسام" aria-label="Permalink to &quot;4. مواصلات کی سطح اور خدمات کی اقسام&quot;">​</a></h2><p>طیاروں کے درمیان مواصلات بینڈوڈتھ اور ترجیح کے مطابق متعدد خدمات کی سطحوں میں تقسیم کیا جاتا ہے:</p><table tabindex="0"><thead><tr><th>سطح</th><th>نام</th><th>بینڈوڈتھ کی حد</th><th>عام استعمال</th><th>ترجیح</th></tr></thead><tbody><tr><td>خصوصی سطح</td><td>اینکر خصوصی چینل</td><td>≥10^15 بٹ/سیکنڈ</td><td>اینکر سنکرونائزیشن، جہت کی بلندی کے آپریشن</td><td>سب سے زیادہ</td></tr><tr><td>پہلی سطح</td><td>تہذیب کی سطح کی مواصلات</td><td>10^12—10^15 بٹ/سیکنڈ</td><td>طیاروں کے درمیان سرکاری مواصلات، ہنگامی نشریات</td><td>زیادہ</td></tr><tr><td>دوسری سطح</td><td>ادارے کی سطح کی مواصلات</td><td>10^9—10^12 بٹ/سیکنڈ</td><td>تحقیقی ادارے، بڑی کاروباری ادارے، تعلیمی نیٹ ورک</td><td>درمیانہ</td></tr><tr><td>تیسری سطح</td><td>تجارتی مواصلات</td><td>10^6—10^9 بٹ/سیکنڈ</td><td>تجارتی مواصلات، میڈیا کی ترسیل</td><td>عام</td></tr><tr><td>چوتھی سطح</td><td>شہری مواصلات</td><td>≤10^6 بٹ/سیکنڈ</td><td>ذاتی مواصلات، روزمرہ کی معلومات</td><td>بنیادی</td></tr></tbody></table><p>تمام سطحوں کی مواصلاتی خدمات &quot;بنیادی مفت، قدرتی اضافے کی فیس&quot; کے اصول پر عمل کرتی ہیں۔ شہری سطح کی بنیادی مواصلاتی خدمات سمبیوٹک تہذیب کے ذریعے مفت فراہم کی جاتی ہیں، جو مواصلات کے شعبے میں &quot;ہر ایک کے پاس راستہ ہے&quot; کو یقینی بناتی ہیں؛ اعلیٰ بینڈوڈتھ، اعلیٰ ترجیح کی قدرتی اضافے کی خدمات توانائی کی کھپت کے مطابق معقول فیس وصول کرتی ہیں۔</p><h2 id="_5-مواصلاتی-سلامتی-اور-اخلاقیات" tabindex="-1">5. مواصلاتی سلامتی اور اخلاقیات <a class="header-anchor" href="#_5-مواصلاتی-سلامتی-اور-اخلاقیات" aria-label="Permalink to &quot;5. مواصلاتی سلامتی اور اخلاقیات&quot;">​</a></h2><p>طیاروں کے درمیان مواصلات کی سلامتی اور اخلاقیات کو سخت طریقے سے منظم کیا جاتا ہے:</p><ul><li><strong>انکرپشن کا معیار</strong>: تمام طیاروں کے درمیان مواصلات میں اینکر سطح کے اینڈ ٹو اینڈ انکرپشن کو اپنانا چاہیے، انکرپشن کی کلید اینکر نیٹ ورک کے حقیقی بے ترتیب نمبر جنریٹر کے ذریعے تیار کی جاتی ہے، نظریاتی طور پر توڑنا ناممکن ہے</li><li><strong>رازداری کا تحفظ</strong>: مواصلات کے مواد کو سمبیوٹک آئین اور صارفین کے تحفظ کے قانون کے دوہرے تحفظ سے تحفظ حاصل ہے، کوئی بھی تنظیم اور فرد غیر مجاز حالت میں مواصلاتی معلومات کو سننے یا روکنے سے قاصر ہے</li><li><strong>معلوماتی آلودگی کی روک تھام</strong>: مواصلاتی نیٹ ورک میں قانون کی سطح کا معلوماتی فلٹرنگ سسٹم لگا ہوا ہے، جو لوٹ مار کے سادگی کے طریقے، نقصان دہ شعور کے پیٹرن جیسی خطرناک معلومات کو مواصلاتی نیٹ ورک کے ذریعے پھیلنے سے روکتا ہے</li><li><strong>ہنگامی نشریات کا اختیار</strong>: تہذیب کی سطح کی ہنگامی حالت میں، سمبیوٹک گورننس ادارے کے پاس خصوصی چینل کے ذریعے تمام طیاروں پر ہنگامی نشریات جاری کرنے کا اختیار ہے، یہ اختیار سخت قانونی نگرانی میں ہے</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>طیاروں کے درمیان مواصلاتی ٹیکنالوجی اینکر سمبیوٹک تہذیب کا &quot;اعصابی نظام&quot; ہے۔ یہ ان گنت طیاروں میں بکھری ہوئی زندگی کو ایک متحد معلوماتی برادری سے جوڑتا ہے، جو سمبیوٹک نیٹ ورک کے تاثرات اور ہم آہنگی کو ممکن بناتا ہے۔ مواصلاتی بینڈوڈتھ میں مسلسل اضافے اور تاخیر میں مسلسل کمی کے ساتھ ساتھ، ہینگیوانزھو &quot;تمام نسلوں کی ریئل ٹائم مشترکہ احساس&quot; کی سمت ارتقاء کر رہا ہے، جس نے شعور کے ارتقاء کے مرحلے میں اجتماعی شعور کی سمبیوسس کے لیے مواصلاتی بنیاد رکھی ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>62-خلائی قانون کی ٹیکنالوجی کا نفاذ</li><li>67-اینکر ہارڈویئر اور بنیادی ڈھانچہ</li><li>21-سمبیوٹک نیٹ ورک کے کام کا اصول</li></ul>',24)])])}const p=d(o,[["render",l]]);export{b as __pageData,p as default};
